import{_ as e,c as a,o as i,al as o}from"./chunks/framework.D8UyiDWg.js";const c=JSON.parse('{"title":"Rover Configuration/Tuning","description":"","frontmatter":{},"headers":[],"relativePath":"zh/config_rover/index.md","filePath":"zh/config_rover/index.md"}'),s={name:"zh/config_rover/index.md"};function r(l,t,n,d,h,u){return i(),a("div",null,t[0]||(t[0]=[o(`<h1 id="rover-configuration-tuning" tabindex="-1">Rover Configuration/Tuning <a class="header-anchor" href="#rover-configuration-tuning" aria-label="Permalink to &quot;Rover Configuration/Tuning&quot;">​</a></h1><p>This topic provides a step-by-step guide for setting up your rover.</p><p>Successive steps enable <a href="./../flight_modes_rover/">drive modes</a> with more autopilot support and features:</p><table tabindex="0"><thead><tr><th>Step</th><th>配置</th><th>Unlocked PX4 Drive Mode</th></tr></thead><tbody><tr><td>1</td><td><a href="./basic_setup.html">Basic Setup</a></td><td><a href="./../flight_modes_rover/manual.html#manual-mode">Full manual mode</a></td></tr><tr><td>2</td><td><a href="./rate_tuning.html">Rate Tuning</a></td><td><a href="./../flight_modes_rover/manual.html#acro-mode">Manual acro mode</a></td></tr><tr><td>3</td><td><a href="./attitude_tuning.html">Attitude Tuning</a></td><td><a href="./../flight_modes_rover/manual.html#stabilized-mode">Manual stabilized mode</a></td></tr><tr><td>4</td><td><a href="./velocity_tuning.html">Velocity Tuning</a></td><td><a href="./../flight_modes_rover/manual.html#manual-mode">Manual position mode</a></td></tr><tr><td>5</td><td><a href="./position_tuning.html">Position Tuning</a></td><td><a href="./../flight_modes_rover/auto.html">Auto modes</a></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>A drive mode will only work properly if all the configuration for the preceding modes has been completed.</p></div><h2 id="flashing-the-rover-build" tabindex="-1">Flashing the Rover Build <a class="header-anchor" href="#flashing-the-rover-build" aria-label="Permalink to &quot;Flashing the Rover Build&quot;">​</a></h2><p>Rovers use a custom build that must be flashed onto your flight controller instead of the default PX4 build:</p><ol><li><p>First build the rover firmware for your flight controller from the <code>main</code> branch (there is no release build, so you can&#39;t just select this build from QGroundControl).</p><p>To build for rover with the <code>make</code> command, replace the <code>_default</code> suffix with <code>_rover</code>. For example, to build rover for px4_fmu-v6x boards, you would use the command:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> px4_fmu-v6x_rover</span></span></code></pre></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p>You can also enable the modules in default builds by adding these lines to your <a href="./../hardware/porting_guide_config.html">board configuration</a> (e.g. for fmu-v6x you might add them to <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v6x/default.px4board" target="_blank" rel="noreferrer"><code>main/boards/px4/fmu-v6x/default.px4board</code></a>):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CONFIG_MODULES_ROVER_ACKERMANN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">y</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CONFIG_MODULES_ROVER_DIFFERENTIAL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">y</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CONFIG_MODULES_ROVER_MECANUM</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">y</span></span></code></pre></div><p>Note that adding the rover modules may lead to flash overflow, in which case you will need to disable modules that you do not plan to use (such as those related to multicopter or fixed wing).</p></div></li></ol><p>:::</p><ol start="2"><li>Load the <strong>custom firmware</strong> that you just built onto your flight controller (see <a href="./../config/firmware.html#installing-px4-main-beta-or-custom-firmware">Loading Firmware &gt; Installing PX4 Main, Beta or Custom Firmware</a>).</li></ol>`,10)]))}const m=e(s,[["render",r]]);export{c as __pageData,m as default};
